BEGIN;
SET LOCAL search_path = erp, auth, pg_catalog;

-- Forward-only runtime parity with docs/rbac Catalog 2.0.0.
-- Existing role/permission IDs and every user_roles membership are preserved.
ALTER TABLE erp.app_roles ADD COLUMN IF NOT EXISTS catalog_version text;
ALTER TABLE erp.app_roles ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE erp.app_roles ADD COLUMN IF NOT EXISTS deprecated_at timestamptz;
ALTER TABLE erp.app_permissions ADD COLUMN IF NOT EXISTS resource text;
ALTER TABLE erp.app_permissions ADD COLUMN IF NOT EXISTS action text;
ALTER TABLE erp.app_permissions ADD COLUMN IF NOT EXISTS catalog_version text;
ALTER TABLE erp.app_permissions ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE erp.app_permissions ADD COLUMN IF NOT EXISTS deprecated_at timestamptz;
ALTER TABLE erp.app_permissions ADD COLUMN IF NOT EXISTS replacement_permission text[];
ALTER TABLE erp.app_permissions ADD COLUMN IF NOT EXISTS risk_class text;

WITH canonical AS (
  SELECT * FROM jsonb_to_recordset('[{"code":"system-administrator","name":"System Administrator","description":"Administers identities, authorization, system configuration, and controlled recovery.","systemManaged":true,"active":true,"constraints":["cannot-remove-final-active-administrator","cannot-approve-own-privilege-escalation"]},{"code":"operations-manager","name":"Operations Manager","description":"Approves operational transitions, reviews DEUR evidence, and closes Rentals without financial authority.","systemManaged":true,"active":true},{"code":"dispatcher","name":"Dispatcher","description":"Plans customers, projects, rentals, assignments, and dispatch activity.","systemManaged":true,"active":true},{"code":"equipment-coordinator","name":"Equipment Coordinator","description":"Maintains fleet records, availability, assignment coordination, and equipment state.","systemManaged":true,"active":true},{"code":"operator","name":"Operator","description":"Views only own assignments, equipment, shifts, and DEUR history and creates, saves, and submits own DEUR evidence.","systemManaged":true,"active":true,"constraints":["requires-active-canonical-operator-link","one-active-user-per-operator","assigned-records-only","own-deur-history-only"]},{"code":"billing-staff","name":"Billing Officer","description":"Performs billing, collections monitoring, financial reporting, and commercial-terms review without operational approval authority.","systemManaged":true,"active":true},{"code":"management-viewer","name":"Management Viewer","description":"Views executive and financial dashboards, KPIs, and approved report exports without transaction authority.","systemManaged":true,"active":true,"constraints":["read-and-export-only","redacted-exports-only"]},{"code":"maintenance-staff","name":"Maintenance Staff","description":"Schedules and performs maintenance and updates related fleet condition.","systemManaged":true,"active":true},{"code":"read-only-auditor","name":"Auditor","description":"Reads auditable business and authorization evidence and exports approved redacted reports without transaction authority.","systemManaged":true,"active":true,"constraints":["no-secret-or-credential-access","redacted-exports-only","read-and-export-only"]}]'::jsonb)
  AS x(code text,name text,description text,"systemManaged" boolean,active boolean,constraints jsonb)
)
INSERT INTO erp.app_roles(id,code,name,catalog_version,active,deprecated_at)
SELECT 'ROLE-CANON-'||upper(regexp_replace(code,'[^a-zA-Z0-9]+','-','g')),code,name,'2.0.0',active,NULL
FROM canonical
ON CONFLICT(code) DO UPDATE SET
 name=EXCLUDED.name,catalog_version=EXCLUDED.catalog_version,active=EXCLUDED.active,deprecated_at=NULL;

-- Pre-existing legacy roles remain active compatibility authorities for existing
-- users, but are no longer assignable because deprecated_at is populated.
UPDATE erp.app_roles
SET catalog_version='legacy-compatibility',active=true,deprecated_at=coalesce(deprecated_at,clock_timestamp())
WHERE code IN('finance','rental-operations');

