INSERT INTO erp.app_permissions(id,code,name,resource,action,catalog_version,active,deprecated_at,replacement_permission,risk_class)
SELECT 'PERM-CANON-'||upper(regexp_replace(code,'[^a-zA-Z0-9]+','-','g')),code,description,resource,action,'2.0.0',active,
 CASE WHEN deprecated THEN coalesce(clock_timestamp(),now()) ELSE NULL END,
 coalesce("replacementCodes",'{}'::text[]),"riskClass"
FROM canonical
ON CONFLICT(code) DO UPDATE SET
 resource=EXCLUDED.resource,action=EXCLUDED.action,catalog_version=EXCLUDED.catalog_version,
 active=EXCLUDED.active,deprecated_at=EXCLUDED.deprecated_at,
 replacement_permission=EXCLUDED.replacement_permission,risk_class=EXCLUDED.risk_class;

