AS x("roleCode" text,"permissionCode" text);

-- Deterministic parity is scoped to canonical roles and canonical permissions.
-- Later extension permissions outside Catalog 2.0.0 remain attached.
DELETE FROM erp.role_permissions mapping
USING erp.app_roles role,erp.app_permissions permission
WHERE mapping.role_id=role.id AND mapping.permission_id=permission.id
 AND role.code IN (SELECT code FROM jsonb_to_recordset('[{"code":"system-administrator","name":"System Administrator","description":"Administers identities, authorization, system configuration, and controlled recovery.","systemManaged":true,"active":true,"constraints":["cannot-remove-final-active-administrator","cannot-approve-own-privilege-escalation"]},{"code":"operations-manager","name":"Operations Manager","description":"Approves operational transitions, reviews DEUR evidence, and closes Rentals without financial authority.","systemManaged":true,"active":true},{"code":"dispatcher","name":"Dispatcher","description":"Plans customers, projects, rentals, assignments, and dispatch activity.","systemManaged":true,"active":true},{"code":"equipment-coordinator","name":"Equipment Coordinator","description":"Maintains fleet records, availability, assignment coordination, and equipment state.","systemManaged":true,"active":true},{"code":"operator","name":"Operator","description":"Views only own assignments, equipment, shifts, and DEUR history and creates, saves, and submits own DEUR evidence.","systemManaged":true,"active":true,"constraints":["requires-active-canonical-operator-link","one-active-user-per-operator","assigned-records-only","own-deur-history-only"]},{"code":"billing-staff","name":"Billing Officer","description":"Performs billing, collections monitoring, financial reporting, and commercial-terms review without operational approval authority.","systemManaged":true,"active":true},{"code":"management-viewer","name":"Management Viewer","description":"Views executive and financial dashboards, KPIs, and approved report exports without transaction authority.","systemManaged":true,"active":true,"constraints":["read-and-export-only","redacted-exports-only"]},{"code":"maintenance-staff","name":"Maintenance Staff","description":"Schedules and performs maintenance and updates related fleet condition.","systemManaged":true,"active":true},{"code":"read-only-auditor","name":"Auditor","description":"Reads auditable business and authorization evidence and exports approved redacted reports without transaction authority.","systemManaged":true,"active":true,"constraints":["no-secret-or-credential-access","redacted-exports-only","read-and-export-only"]}]'::jsonb) AS x(code text))
 AND permission.catalog_version='2.0.0'
 AND NOT EXISTS(
   SELECT 1 FROM expected_catalog_role_permissions expected
   WHERE expected.role_code=role.code AND expected.permission_code=permission.code
 );

INSERT INTO erp.role_permissions(role_id,permission_id)
SELECT role.id,permission.id
FROM expected_catalog_role_permissions expected
JOIN erp.app_roles role ON role.code=expected.role_code
JOIN erp.app_permissions permission ON permission.code=expected.permission_code
ON CONFLICT(role_id,permission_id) DO NOTHING;

CREATE OR REPLACE VIEW erp.effective_user_permissions AS
SELECT assignment.user_id,permission.code AS permission_code
FROM erp.user_roles assignment
JOIN erp.app_roles role ON role.id=assignment.role_id AND role.active
JOIN erp.role_permissions mapping ON mapping.role_id=role.id
JOIN erp.app_permissions permission ON permission.id=mapping.permission_id AND permission.active;

ALTER VIEW erp.effective_user_permissions SET (security_invoker=true);
REVOKE SELECT ON erp.effective_user_permissions FROM PUBLIC,anon;
GRANT SELECT ON erp.effective_user_permissions TO authenticated;

CREATE OR REPLACE FUNCTION erp.current_user_effective_permissions()
RETURNS TABLE(permission_code text)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=erp,auth,pg_catalog AS $$
 SELECT DISTINCT permission.code
 FROM erp.users caller
 JOIN erp.companies company ON company.id=caller.company_id AND company.active
 JOIN erp.user_roles assignment ON assignment.user_id=caller.id
 JOIN erp.app_roles role ON role.id=assignment.role_id AND role.active
 JOIN erp.role_permissions mapping ON mapping.role_id=role.id
 JOIN erp.app_permissions permission ON permission.id=mapping.permission_id AND permission.active
 WHERE caller.id=auth.uid() AND caller.status='active'
 ORDER BY permission.code
$$;

CREATE OR REPLACE FUNCTION erp.current_user_roles()
RETURNS TABLE(role_code text)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=erp,auth,pg_catalog AS $$
 SELECT DISTINCT role.code
 FROM erp.users caller
 JOIN erp.companies company ON company.id=caller.company_id AND company.active
 JOIN erp.user_roles assignment ON assignment.user_id=caller.id
 JOIN erp.app_roles role ON role.id=assignment.role_id AND role.active
 WHERE caller.id=auth.uid() AND caller.status='active'
 ORDER BY role.code
$$;

CREATE OR REPLACE FUNCTION erp.current_user_has_permission(required_permission text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=erp,auth,pg_catalog AS $$
 SELECT EXISTS(
   SELECT 1 FROM erp.effective_user_permissions p
   WHERE p.user_id=auth.uid() AND p.permission_code=required_permission
 )
 OR (
   auth.role()='service_role'
   AND current_setting('erp.scheduler_preparation',true)='true'
   AND required_permission='deur.review'
   AND EXISTS(
     SELECT 1
     FROM erp.system_principals principal
     JOIN erp.system_principal_permissions permission ON permission.principal_id=principal.id
     WHERE principal.id=nullif(current_setting('erp.system_principal_id',true),'')::uuid
       AND principal.active AND permission.permission_code='grouped_review.schedule'
   )
 )
$$;

REVOKE ALL ON FUNCTION erp.current_user_effective_permissions(),erp.current_user_roles()
FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION erp.current_user_effective_permissions(),erp.current_user_roles()
TO authenticated;
REVOKE EXECUTE ON FUNCTION erp.current_user_has_permission(text)
FROM PUBLIC,anon,authenticated;

DO $$
DECLARE operation_count integer;
BEGIN
 SELECT count(*) INTO operation_count
 FROM erp.role_permissions mapping
 JOIN erp.app_roles role ON role.id=mapping.role_id
 JOIN erp.app_permissions permission ON permission.id=mapping.permission_id
 WHERE role.code='operations-manager' AND permission.catalog_version='2.0.0';
 IF operation_count<>28 THEN RAISE EXCEPTION 'operations-manager must have exactly 28 Catalog 2.0.0 permissions, found %',operation_count;END IF;
 IF NOT EXISTS(
  SELECT 1 FROM erp.role_permissions mapping
  JOIN erp.app_roles role ON role.id=mapping.role_id
  JOIN erp.app_permissions permission ON permission.id=mapping.permission_id
  WHERE role.code='operations-manager' AND permission.code='rental.approval.decide'
 ) THEN RAISE EXCEPTION 'operations-manager lacks rental.approval.decide';END IF;
 IF EXISTS(
  SELECT 1 FROM erp.role_permissions mapping
  JOIN erp.app_roles role ON role.id=mapping.role_id
  JOIN erp.app_permissions permission ON permission.id=mapping.permission_id
  WHERE role.code='finance' AND permission.code='rental.approval.decide'
 ) THEN RAISE EXCEPTION 'finance must not gain rental.approval.decide';END IF;
END $$;

COMMIT;
